export default LoginScreen;

import { get, set, del, clear } from 'idb-keyval';
import { DefectItem, InspectionInfo, AppState, CompletedInspection } from '../types';

const KEYS = {
  STEP: 'app_step',
  INFO: 'app_info',
  DEFECTS: 'app_defects',
  LOCATIONS: 'app_locations',
  DRAFT: 'app_draft',
  ARCHIVE: 'app_archive',
  // Auth keys
  AUTH_TIMESTAMP: 'app_auth_last_active' // LocalStorage (Time check)
};

const SESSION_KEY = 'app_session_active'; // SessionStorage (App kill check)
const ONE_HOUR = 60 * 60 * 1000; // 1 Hour in ms

// --- Auth Helpers ---

// Login: Set both session flag (cleared on app close) and timestamp (for timeout)
export const saveAuth = () => {
  sessionStorage.setItem(SESSION_KEY, 'true');
  localStorage.setItem(KEYS.AUTH_TIMESTAMP, Date.now().toString());
};

// Check Auth: Must have Session AND (Current Time - Last Active < 1 Hour)
export const checkAuth = (): boolean => {
  // 1. Check if App was killed/closed (SessionStorage is cleared on browser/tab close)
  const isSessionActive = sessionStorage.getItem(SESSION_KEY);
  if (!isSessionActive) {
    return false;
  }

  // 2. Check 1 Hour Timeout
  const lastActiveStr = localStorage.getItem(KEYS.AUTH_TIMESTAMP);
  if (!lastActiveStr) {
    return false; 
  }

  const lastActive = parseInt(lastActiveStr, 10);
  const now = Date.now();

  if (now - lastActive > ONE_HOUR) {
    // Timeout expired
    clearAuth();
    return false;
  }

  // 3. If valid, refresh the timestamp
  updateAuthTimestamp();
  return true;
};

// Refresh the 1-hour timer (called on user interaction)
export const updateAuthTimestamp = () => {
  if (sessionStorage.getItem(SESSION_KEY)) {
    localStorage.setItem(KEYS.AUTH_TIMESTAMP, Date.now().toString());
  }
};

export const clearAuth = () => {
  sessionStorage.removeItem(SESSION_KEY);
  localStorage.removeItem(KEYS.AUTH_TIMESTAMP);
};

// --- Basic Data Access ---
export const saveStep = (step: AppState['step']) => set(KEYS.STEP, step);
export const saveInfo = (info: InspectionInfo) => set(KEYS.INFO, info);
export const saveLocations = (locations: string[]) => set(KEYS.LOCATIONS, locations);

export const loadStep = () => get<AppState['step']>(KEYS.STEP);
export const loadInfo = () => get<InspectionInfo>(KEYS.INFO);
export const loadLocations = () => get<string[]>(KEYS.LOCATIONS);

// --- Handle Defects with Blobs ---
export const saveDefects = async (defects: DefectItem[]) => {
  const defectsWithBlobs = await Promise.all(
    defects.map(async (d) => ({
      ...d,
      farPhotos: await Promise.all(d.farPhotos.map(async (url) => {
        const res = await fetch(url);
        return await res.blob();
      })),
      nearPhotos: await Promise.all(d.nearPhotos.map(async (url) => {
        const res = await fetch(url);
        return await res.blob();
      }))
    }))
  );
  await set(KEYS.DEFECTS, defectsWithBlobs);
};

export const loadDefects = async (): Promise<DefectItem[]> => {
  const saved = await get<any[]>(KEYS.DEFECTS);
  if (!saved) return [];
  return saved.map((d) => ({
    ...d,
    farPhotos: d.farPhotos.map((blob: Blob) => URL.createObjectURL(blob)),
    nearPhotos: d.nearPhotos.map((blob: Blob) => URL.createObjectURL(blob))
  }));
};

// --- Draft Handling ---
export const saveDraft = async (data: {
  location: string;
  farPhotos: string[];
  nearPhotos: string[];
  description: string;
  editingId: string | null;
}) => {
  const farBlobs = await Promise.all(data.farPhotos.map(url => fetch(url).then(r => r.blob())));
  const nearBlobs = await Promise.all(data.nearPhotos.map(url => fetch(url).then(r => r.blob())));
  await set(KEYS.DRAFT, { ...data, farPhotos: farBlobs, nearPhotos: nearBlobs });
};

export const loadDraft = async () => {
  const draft = await get<any>(KEYS.DRAFT);
  if (!draft) return null;
  return {
    ...draft,
    farPhotos: draft.farPhotos.map((b: Blob) => URL.createObjectURL(b)),
    nearPhotos: draft.nearPhotos.map((b: Blob) => URL.createObjectURL(b))
  };
};

export const clearDraft = () => del(KEYS.DRAFT);

export const clearAllData = async () => {
  await del(KEYS.STEP);
  await del(KEYS.INFO);
  await del(KEYS.DEFECTS);
  await del(KEYS.LOCATIONS);
  await del(KEYS.DRAFT);
};

// --- Archive Handling ---
export const saveToArchive = async (info: InspectionInfo, defects: DefectItem[], locations: string[]) => {
  let currentArchive = await get<any[]>(KEYS.ARCHIVE);
  if (!Array.isArray(currentArchive)) currentArchive = [];

  const defectsWithBlobs = await Promise.all(
    defects.map(async (d) => ({
      ...d,
      farPhotos: await Promise.all(d.farPhotos.map(url => fetch(url).then(r => r.blob()))),
      nearPhotos: await Promise.all(d.nearPhotos.map(url => fetch(url).then(r => r.blob())))
    }))
  );

  const newItem: CompletedInspection = {
    id: Date.now().toString(),
    info,
    defects: defectsWithBlobs as unknown as DefectItem[],
    locations,
    savedAt: Date.now()
  };

  await set(KEYS.ARCHIVE, [newItem, ...currentArchive]);
};

export const loadArchive = async (): Promise<CompletedInspection[]> => {
  const archive = await get<any[]>(KEYS.ARCHIVE);
  return Array.isArray(archive) ? archive : [];
};

export const restoreArchivedItem = (item: any): { defects: DefectItem[] } => {
  if (!item) return { defects: [] };
  const restoredDefects = (item.defects || []).map((d: any) => ({
    ...d,
    farPhotos: (d.farPhotos || []).map((b: Blob) => URL.createObjectURL(b)),
    nearPhotos: (d.nearPhotos || []).map((b: Blob) => URL.createObjectURL(b))
  }));
  return { defects: restoredDefects };
};

export const deleteFromArchive = async (id: string) => {
  const currentArchive = await get<CompletedInspection[]>(KEYS.ARCHIVE);
  const newArchive = (currentArchive || []).filter(item => item.id !== id);
  await set(KEYS.ARCHIVE, newArchive);
  return newArchive;
};

// --- TEAM COLLABORATION (REFACTORED FOR STABILITY) ---

const blobToBase64 = (blob: Blob): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
        const result = reader.result as string;
        resolve(result);
    };
    reader.onerror = (e) => reject(e);
    reader.readAsDataURL(blob);
  });
};

const base64ToBlob = async (base64: string): Promise<Blob> => {
  try {
      const res = await fetch(base64);
      return await res.blob();
  } catch (e) {
      console.error("Error converting base64 to blob", e);
      throw new Error("이미지 변환 실패");
  }
};

const generateUniqueId = () => {
    return Date.now().toString(36) + Math.random().toString(36).substring(2, 5);
};

// 1. Export Data (Generate JSON file)
export const exportActiveDataToDataFile = async (info: InspectionInfo, defects: DefectItem[]): Promise<Blob> => {
  try {
      // Process defects sequentially or in small batches if needed, 
      // but Promise.all is usually fine unless 100+ images are involved.
      const serializableDefects = await Promise.all(defects.map(async (d) => {
        // Convert Blobs to Base64 strings
        const farPhotosB64 = await Promise.all(d.farPhotos.map(async url => {
            const blob = await (await fetch(url)).blob();
            return blobToBase64(blob);
        }));
        const nearPhotosB64 = await Promise.all(d.nearPhotos.map(async url => {
            const blob = await (await fetch(url)).blob();
            return blobToBase64(blob);
        }));

        return {
            ...d,
            farPhotos: farPhotosB64,
            nearPhotos: nearPhotosB64
        };
      }));

      const data = {
        version: '2.0',
        type: 'DOUBLECHECK_TEAM_DATA',
        info, // Include info for reference, though we might not overwrite it
        defects: serializableDefects,
        exportedAt: Date.now()
      };

      const jsonString = JSON.stringify(data);
      return new Blob([jsonString], { type: 'application/json' });
  } catch (e) {
      console.error("Export Error:", e);
      throw new Error("데이터 내보내기 중 오류가 발생했습니다. 사진 용량이 너무 클 수 있습니다.");
  }
};

// 2. Import Data (Merge Logic)
export const mergeActiveDataFromFile = async (file: File): Promise<{ mergedDefects: DefectItem[], newLocations: string[] }> => {
  try {
      const text = await file.text();
      let parsed;
      try {
          parsed = JSON.parse(text);
      } catch (e) {
          throw new Error("파일을 읽을 수 없습니다. 올바른 JSON 파일인지 확인해주세요.");
      }

      if (parsed.type !== 'DOUBLECHECK_TEAM_DATA') {
        throw new Error("이 앱에서 생성된 데이터 파일이 아닙니다.");
      }

      const importedDefectsRaw = parsed.defects || [];
      const newLocations: string[] = [];

      // Convert Base64 strings back to Blob URLs and assign NEW IDs
      const restoredDefects = await Promise.all(importedDefectsRaw.map(async (d: any) => {
         // Create new unique ID to ensure append works (avoid overwriting existing keys)
         const newId = generateUniqueId();

         const farPhotos = await Promise.all((d.farPhotos || []).map(async (b64: string) => {
             const blob = await base64ToBlob(b64);
             return URL.createObjectURL(blob);
         }));

         const nearPhotos = await Promise.all((d.nearPhotos || []).map(async (b64: string) => {
             const blob = await base64ToBlob(b64);
             return URL.createObjectURL(blob);
         }));

         // Collect location to update location list later
         if (d.location && typeof d.location === 'string') {
             newLocations.push(d.location);
         }

         return {
             ...d,
             id: newId, // Override ID
             farPhotos,
             nearPhotos,
             timestamp: d.timestamp || Date.now()
         };
      }));

      return {
          mergedDefects: restoredDefects,
          newLocations: [...new Set(newLocations)] // Return unique new locations
      };

  } catch (err: any) {
      console.error("Merge Error:", err);
      throw new Error(err.message || "데이터 합치기에 실패했습니다.");
  }
};

export const exportArchiveData = async () => {
  const archive = await loadArchive();
  const serializableArchive = await Promise.all(archive.map(async (item: any) => {
    const defects = await Promise.all(item.defects.map(async (d: any) => ({
      ...d,
      farPhotos: await Promise.all(d.farPhotos.map((b: Blob) => blobToBase64(b))),
      nearPhotos: await Promise.all(d.nearPhotos.map((b: Blob) => blobToBase64(b)))
    })));
    return { ...item, defects };
  }));
  return JSON.stringify(serializableArchive);
};

export const importArchiveData = async (jsonString: string) => {
  const parsedArchive = JSON.parse(jsonString);
  const restoredArchive = await Promise.all(parsedArchive.map(async (item: any) => {
    const defects = await Promise.all(item.defects.map(async (d: any) => ({
      ...d,
      farPhotos: await Promise.all(d.farPhotos.map((b64: string) => base64ToBlob(b64))),
      nearPhotos: await Promise.all(d.nearPhotos.map((b64: string) => base64ToBlob(b64)))
    })));
    return { ...item, id: generateUniqueId(), defects, savedAt: Date.now() };
  }));
  let currentArchive = await get<any[]>(KEYS.ARCHIVE) || [];
  await set(KEYS.ARCHIVE, [...restoredArchive, ...currentArchive]);
  return restoredArchive;
};

import React, { useState, useEffect, useRef } from 'react';
import InfoForm from './components/InfoForm';
import CaptureScreen from './components/CaptureScreen';
import ArchiveScreen from './components/ArchiveScreen';
import LoginScreen from './components/LoginScreen';
import { AppState, InspectionInfo, DefectItem } from './types';
import { generatePDF, getMatchingStandard } from './services/pdfService';
import { 
  loadStep, loadInfo, loadDefects, loadLocations, 
  saveStep, saveInfo, saveDefects, saveLocations, clearAllData, saveToArchive, checkAuth, clearAuth, updateAuthTimestamp
} from './services/storage';
import { ArrowLeft, FileText, Download, MapPin, Loader2, Archive, Copy, CheckCircle, RotateCcw, Wifi, WifiOff, LogOut } from 'lucide-react';
import { AnimatePresence } from 'framer-motion';
import PhotoViewer from './components/PhotoViewer';

const getLocalISOString = () => {
  const now = new Date();
  const offsetMs = now.getTimezoneOffset() * 60 * 1000;
  // Round to nearest 10 minutes
  const coeff = 1000 * 60 * 10;
  const rounded = new Date(Math.round(now.getTime() / coeff) * coeff);
  const localISOTime = (new Date(rounded.getTime() - offsetMs)).toISOString().slice(0, 16);
  return localISOTime;
};

const INITIAL_INFO: InspectionInfo = {
  apartmentName: '',
  unit: '',
  typeSize: '',
  inspectorName: '',
  phoneNumber: '',
  date: getLocalISOString()
};

// Default categories for 84sqm apartment
const DEFAULT_LOCATIONS = [
  '현관', '현관창고', '공용욕실', '침실3', '침실2', '복도', 
  '펜트리', '거실', '주방', '다용도실', '침실1', '발코니', 
  '실외기실', '대피공간', '드레스룸', '부부욕실'
];

const App: React.FC = () => {
  const [isLoading, setIsLoading] = useState(true);
  const [isAuthorized, setIsAuthorized] = useState(false); // Auth State

  const [step, setStep] = useState<AppState['step']>('info');
  // Track the previous step to allow returning from Archive
  const [lastStep, setLastStep] = useState<AppState['step']>('info');

  const [info, setInfo] = useState<InspectionInfo>(INITIAL_INFO);
  const [defects, setDefects] = useState<DefectItem[]>([]);
  const [locations, setLocations] = useState<string[]>(DEFAULT_LOCATIONS);
  const [isGenerating, setIsGenerating] = useState(false);
  const [showFinishModal, setShowFinishModal] = useState(false);

  // Network Status State
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Photo Viewer State for Preview
  const [viewerState, setViewerState] = useState<{
    isOpen: boolean;
    photos: string[];
    index: number;
  }>({ isOpen: false, photos: [], index: 0 });

  // Use a ref to track if initial load is done to prevent overwriting storage with initial empty state
  const isLoadedRef = useRef(false);

  // Initialize app: Load data from IndexedDB
  useEffect(() => {
    const initApp = async () => {
      try {
        // 1. Check Auth (Validation only)
        const hasAuth = checkAuth();
        setIsAuthorized(hasAuth);

        // 2. Load Data (Always load, even if auth fails, so data is ready upon relogin)
        const [savedStep, savedInfo, savedDefects, savedLocations] = await Promise.all([
          loadStep(),
          loadInfo(),
          loadDefects(),
          loadLocations()
        ]);

        if (savedStep) setStep(savedStep);
        if (savedInfo) setInfo(savedInfo);
        if (savedDefects) setDefects(savedDefects);
        if (savedLocations) setLocations(savedLocations);
      } catch (error) {
        console.error("Failed to load saved data", error);
      } finally {
        setIsLoading(false);
        isLoadedRef.current = true;
      }
    };

    initApp();
  }, []);

  // Monitor App Visibility (Background/Foreground)
  useEffect(() => {
    const handleVisibilityChange = () => {
      // When app comes back to foreground
      if (document.visibilityState === 'visible') {
        const isValid = checkAuth();
        // If timed out or session lost, force logout
        if (!isValid) {
          setIsAuthorized(false);
        } else {
          // If valid, just ensure state matches
          setIsAuthorized(true);
        }
      }
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => document.removeEventListener('visibilitychange', handleVisibilityChange);
  }, []);

  // Monitor User Activity to Refresh Session (Prevent timeout while working)
  useEffect(() => {
    if (!isAuthorized) return;

    const handleUserActivity = () => {
      updateAuthTimestamp();
    };

    // Listen to common interaction events
    window.addEventListener('click', handleUserActivity);
    window.addEventListener('touchstart', handleUserActivity);
    window.addEventListener('keydown', handleUserActivity);

    return () => {
      window.removeEventListener('click', handleUserActivity);
      window.removeEventListener('touchstart', handleUserActivity);
      window.removeEventListener('keydown', handleUserActivity);
    };
  }, [isAuthorized]);

  // Monitor Network Status
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Prevent accidental back navigation
  useEffect(() => {
    // Push current state to history to create a buffer
    history.pushState(null, '', window.location.href);

    const handlePopState = () => {
      // When back button is pressed, push state again to stay on page
      history.pushState(null, '', window.location.href);
    };

    window.addEventListener('popstate', handlePopState);
    return () => {
      window.removeEventListener('popstate', handlePopState);
    };
  }, []);

  // Persist state changes
  useEffect(() => {
    if (isLoadedRef.current) saveStep(step);
  }, [step]);

  useEffect(() => {
    if (isLoadedRef.current) saveInfo(info);
  }, [info]);

  useEffect(() => {
    if (isLoadedRef.current) saveDefects(defects);
  }, [defects]);

  useEffect(() => {
    if (isLoadedRef.current) saveLocations(locations);
  }, [locations]);

  const handleInfoSubmit = (data: InspectionInfo) => {
    setInfo(data);
    setStep('capture');
  };

  const handleGenerateReport = async () => {
    setIsGenerating(true);
    setTimeout(async () => {
      await generatePDF(info, defects);
      setIsGenerating(false);
    }, 100);
  };

  const handleCopyText = () => {
    if (defects.length === 0) {
      alert('복사할 하자 내역이 없습니다.');
      return;
    }

    const dateStr = new Date(info.date).toLocaleString('ko-KR');

    let text = `[사전점검 리포트 - Double Check]\n\n`;
    text += `■ 현장 정보\n`;
    text += `- 현장명: ${info.apartmentName}\n`;
    text += `- 호수: ${info.unit}\n`;
    text += `- 타입: ${info.typeSize}\n`;
    text += `- 이름: ${info.inspectorName} (${info.phoneNumber})\n`;
    text += `- 점검일: ${dateStr}\n`;
    text += `\n================================\n\n`;
    text += `■ 하자 세부 내역 (총 ${defects.length}건)\n\n`;

    // Group by location
    const grouped = defects.reduce((acc, d) => {
      (acc[d.location] = acc[d.location] || []).push(d);
      return acc;
    }, {} as Record<string, DefectItem[]>);

    // Sort locations by their order in the locations array
    const sortedLocs = locations.filter(loc => grouped[loc]);

    sortedLocs.forEach(loc => {
      text += `[${loc}]\n`;
      grouped[loc].forEach((d, i) => {
        text += `${i + 1}. ${d.description}\n`;
      });
      text += '\n';
    });

    navigator.clipboard.writeText(text).then(() => {
      alert('고객 정보와 하자 내역이 모두 복사되었습니다.');
    }).catch(err => {
      console.error('Failed to copy: ', err);
      alert('텍스트 복사에 실패했습니다.');
    });
  };

  const handleCompleteClick = () => {
    setShowFinishModal(true);
  };

  const confirmCompleteAndArchive = async () => {
    setShowFinishModal(false);
    setIsLoading(true);

    try {
      // 1. Archive current data
      await saveToArchive(info, defects, locations);

      // 2. Clear active data
      await clearAllData();
      localStorage.removeItem('info_form_draft');

      // 3. Reset State
      setInfo({ ...INITIAL_INFO, date: getLocalISOString() });
      setDefects([]);
      setLocations(DEFAULT_LOCATIONS);
      setStep('info');

      alert('저장이 완료되었습니다. 보관함에서 언제든지 내역을 확인하고 수정할 수 있습니다.');
    } catch (e) {
      console.error(e);
      alert('저장 중 오류가 발생했습니다. 잠시 후 다시 시도해주세요.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleReset = async () => {
    if (confirm('모든 데이터가 초기화됩니다 (보관되지 않음). 처음으로 돌아가시겠습니까?')) {
      setIsLoading(true);
      await clearAllData();
      setStep('info');
      setDefects([]);
      setLocations(DEFAULT_LOCATIONS);
      setInfo(INITIAL_INFO);
      localStorage.removeItem('info_form_draft'); 
      isLoadedRef.current = true;
      setIsLoading(false);
    }
  };

  const handleLogout = () => {
    if (confirm('보안을 위해 앱을 잠그시겠습니까?')) {
      clearAuth();
      setIsAuthorized(false);
    }
  };

  const handleLoadArchive = (archivedInfo: InspectionInfo, archivedDefects: DefectItem[], archivedLocations: string[]) => {
    setInfo(archivedInfo);
    setDefects(archivedDefects);
    setLocations(archivedLocations);
    setStep('preview'); // Go straight to preview to check/download
  };

  const openPhotoViewer = (photos: string[], index: number) => {
    setViewerState({
      isOpen: true,
      photos,
      index
    });
  };

  // Group defects by location for preview
  const groupedDefects = defects.reduce((acc, defect) => {
    (acc[defect.location] = acc[defect.location] || []).push(defect);
    return acc;
  }, {} as Record<string, DefectItem[]>);

  const activeLocationsInPreview = Object.keys(groupedDefects);

  if (isLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50 text-gray-500">
        <Loader2 size={40} className="animate-spin text-brand-600 mb-4" />
        <p>데이터 처리 중...</p>
      </div>
    );
  }

  // SHOW LOGIN SCREEN IF NOT AUTHORIZED
  if (!isAuthorized) {
    return <LoginScreen onSuccess={() => setIsAuthorized(true)} />;
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col pt-safe relative">
      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-20">
        {/* Offline Banner */}
        {!isOnline && (
          <div className="bg-gray-800 text-white text-xs py-2 px-4 text-center flex items-center justify-center gap-2 animate-in slide-in-from-top">
            <WifiOff size={14} className="text-red-400" />
            <span>오프라인 모드: 인터넷이 없어도 작성 내용은 기기에 안전하게 저장됩니다.</span>
          </div>
        )}

        <div className="px-4 py-3 max-w-md mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            {step !== 'info' && step !== 'archive' && (
              <button 
                onClick={() => setStep(step === 'preview' ? 'capture' : 'info')}
                className="p-2 -ml-2 rounded-full hover:bg-gray-100 text-gray-600"
              >
                <ArrowLeft size={20} />
              </button>
            )}
            <h1 className="font-bold text-gray-800 text-lg flex items-center gap-2">
              <FileText className="text-brand-600" size={24} />
              Double Check
            </h1>
          </div>
          <div className="flex items-center gap-2">
            {step === 'capture' && defects.length > 0 && (
               <button onClick={handleReset} className="text-xs text-red-500 font-medium px-2 py-1 rounded hover:bg-red-50">
                 초기화
               </button>
            )}
            {step === 'info' && (
               <button onClick={handleLogout} className="text-gray-400 p-2 hover:bg-gray-100 rounded-full" title="잠금(로그아웃)">
                 <LogOut size={20}/>
               </button>
            )}
            {step !== 'archive' && (
              <button 
                onClick={() => {
                  setLastStep(step);
                  setStep('archive');
                }}
                className="text-gray-600 p-2 hover:bg-gray-100 rounded-full"
                title="보관함"
              >
                <Archive size={22} />
              </button>
            )}
          </div>
        </div>
      </header>

      {/* Content */}
      <main className="flex-1 p-4 max-w-md mx-auto w-full">
        {step === 'info' && (
          <InfoForm initialData={info} onSubmit={handleInfoSubmit} />
        )}

        {step === 'capture' && (
          <CaptureScreen 
            defects={defects} 
            setDefects={setDefects}
            locations={locations}
            setLocations={setLocations}
            onFinish={() => setStep('preview')} 
          />
        )}

        {step === 'archive' && (
          <ArchiveScreen 
            onLoad={handleLoadArchive}
            onGoBack={() => setStep(lastStep)}
            onGoHome={() => setStep('info')}
          />
        )}

        {step === 'preview' && (
          <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden pb-44">
            <div className="p-6 border-b border-gray-100 flex justify-between items-center">
              <div>
                <h2 className="text-xl font-bold text-gray-800 mb-1">보고서 미리보기</h2>
                <p className="text-sm text-gray-500">내용을 확인하고 저장하세요.</p>
              </div>
              <button
                onClick={handleCopyText}
                className="text-brand-600 bg-brand-50 hover:bg-brand-100 px-3 py-1.5 rounded-lg text-sm font-bold flex items-center gap-1 transition"
              >
                <Copy size={14} />
                텍스트 복사
              </button>
            </div>

            <div className="p-6 bg-gray-50 text-sm space-y-4">
              <div className="bg-white p-4 rounded-lg border border-gray-200">
                <h3 className="font-bold text-gray-800 mb-3 border-b pb-2">기본 정보</h3>
                <div className="grid grid-cols-2 gap-y-2 gap-x-4">
                  <span className="text-gray-500">현장명</span> <span className="font-medium text-right">{info.apartmentName}</span>
                  <span className="text-gray-500">동/호수</span> <span className="font-medium text-right">{info.unit}</span>
                  <span className="text-gray-500">타입</span> <span className="font-medium text-right">{info.typeSize}</span>
                  <span className="text-gray-500">이름</span> <span className="font-medium text-right">{info.inspectorName}</span>
                  <span className="text-gray-500">일시</span> <span className="font-medium text-right">{new Date(info.date).toLocaleString('ko-KR')}</span>
                </div>
              </div>

              <div className="space-y-6">
                <h3 className="font-bold text-gray-800 ml-1 text-lg">하자 내역 (총 {defects.length}건)</h3>

                {activeLocationsInPreview.length === 0 ? (
                  <p className="text-center text-gray-400 py-4">등록된 하자가 없습니다.</p>
                ) : (
                  activeLocationsInPreview.map((loc) => (
                    <div key={loc} className="space-y-3">
                      <div className="flex items-center gap-2 border-b border-gray-200 pb-1">
                        <MapPin size={16} className="text-brand-600" />
                        <h4 className="font-bold text-gray-800 text-base">{loc}</h4>
                        <span className="text-xs bg-gray-100 text-gray-600 px-2 py-0.5 rounded-full">{groupedDefects[loc].length}건</span>
                      </div>

                      {groupedDefects[loc].map((d, i) => {
                        const standard = getMatchingStandard(d.description);
                        const allPhotos = [...d.farPhotos, ...d.nearPhotos];

                        return (
                          <div key={d.id} className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm">
                            <div className="flex items-center gap-2 mb-3">
                              <span 
                                className="flex-shrink-0 w-6 h-6 text-white rounded-full flex items-center justify-center text-xs font-bold"
                                style={{ backgroundColor: 'rgb(0, 15, 85)' }}
                              >
                                {i + 1}
                              </span>
                              <p className="font-bold text-gray-800 line-clamp-1 flex-1">{d.description}</p>
                            </div>

                            <div className="grid grid-cols-5 gap-1 mb-3">
                              {d.farPhotos.map((p, idx) => (
                                <div key={`far-${idx}`} className="aspect-square bg-gray-100 rounded overflow-hidden relative border border-green-200 cursor-zoom-in" onClick={() => openPhotoViewer(allPhotos, idx)}>
                                  <img src={p} className="w-full h-full object-cover" />
                                  <div className="absolute bottom-0 left-0 right-0 bg-green-500/80 h-1.5"></div>
                                </div>
                              ))}
                              {d.nearPhotos.map((p, idx) => (
                                <div key={`near-${idx}`} className="aspect-square bg-gray-100 rounded overflow-hidden relative border border-blue-200 cursor-zoom-in" onClick={() => openPhotoViewer(allPhotos, d.farPhotos.length + idx)}>
                                  <img src={p} className="w-full h-full object-cover" />
                                  <div className="absolute bottom-0 left-0 right-0 bg-blue-500/80 h-1.5"></div>
                                </div>
                              ))}
                            </div>

                            {standard && (
                              <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-3 text-xs">
                                <h5 className="font-bold text-yellow-800 flex items-center gap-2 mb-1">
                                  <span className="bg-yellow-600 text-white text-[10px] px-1.5 py-0.5 rounded">관련 기준</span>
                                  {standard.title}
                                </h5>
                                <p className="text-gray-700 whitespace-pre-wrap leading-relaxed">{standard.content}</p>
                              </div>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  ))
                )}
              </div>
            </div>

            <div className="fixed bottom-0 left-0 right-0 p-4 pb-safe bg-white/90 backdrop-blur-md border-t border-gray-200 z-10 space-y-2">
              <button
                onClick={handleGenerateReport}
                disabled={isGenerating}
                className="w-full max-w-md mx-auto bg-brand-600 hover:bg-brand-700 text-white font-bold py-3.5 px-6 rounded-xl shadow-lg flex items-center justify-center gap-2 transition disabled:opacity-70 disabled:cursor-wait"
              >
                {isGenerating ? (
                  <>
                    <Loader2 className="animate-spin" size={20} />
                    PDF 생성 중...
                  </>
                ) : (
                  <>
                    <Download size={20} />
                    PDF 다운로드
                  </>
                )}
              </button>

              <div className="grid grid-cols-2 gap-2 max-w-md mx-auto">
                 <button
                  onClick={handleCompleteClick}
                  className="bg-gray-800 hover:bg-gray-900 text-white font-bold py-3 px-4 rounded-xl flex items-center justify-center gap-2 transition"
                >
                  <CheckCircle size={18} />
                  점검 완료 및 보관
                </button>
                <button
                  onClick={() => setStep('capture')}
                  className="bg-white border border-gray-300 text-gray-700 font-bold py-3 px-4 rounded-xl hover:bg-gray-50 transition flex items-center justify-center gap-2"
                >
                  <RotateCcw size={18} />
                  수정하기
                </button>
              </div>
            </div>
          </div>
        )}
      </main>

      {/* Fullscreen Photo Viewer for Preview Mode */}
      <AnimatePresence>
        {viewerState.isOpen && (
          <PhotoViewer 
            photos={viewerState.photos}
            initialIndex={viewerState.index}
            onClose={() => setViewerState(prev => ({ ...prev, isOpen: false }))}
          />
        )}
      </AnimatePresence>

      {/* Confirmation Modal */}
      {showFinishModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl w-full max-w-sm p-6 shadow-xl relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-1 bg-brand-500"></div>

            <div className="flex items-start gap-4 mb-4">
              <div className="bg-brand-100 p-3 rounded-full text-brand-600 flex-shrink-0">
                <CheckCircle size={28} />
              </div>
              <div>
                <h3 className="text-lg font-bold text-gray-900">점검을 완료하시겠습니까?</h3>
                <p className="text-sm text-gray-500 mt-1 leading-relaxed">
                  작성하신 점검 자료를 보관함에 안전하게 저장하고 초기 화면으로 돌아갑니다.
                </p>
              </div>
            </div>

            <div className="bg-gray-50 rounded-xl p-3 mb-6 text-xs text-gray-600 border border-gray-100">
               <ul className="space-y-1 list-disc list-inside">
                 <li>저장된 자료는 <b>보관함</b>에서 다시 불러올 수 있습니다.</li>
                 <li>아직 작성이 끝나지 않았다면 <b>취소</b>를 눌러주세요.</li>
               </ul>
            </div>

            <div className="flex flex-col gap-3">
              <button 
                onClick={confirmCompleteAndArchive}
                className="w-full py-3.5 bg-brand-600 hover:bg-brand-700 text-white font-bold rounded-xl flex items-center justify-center gap-2 transition shadow-sm"
              >
                네, 점검을 완료했습니다
                <span className="text-[10px] font-normal bg-brand-700/50 px-1.5 py-0.5 rounded ml-1">저장 및 종료</span>
              </button>
              <button 
                onClick={() => setShowFinishModal(false)}
                className="w-full py-3.5 bg-white border border-gray-300 text-gray-700 font-bold rounded-xl hover:bg-gray-50 transition"
              >
                아니요, 더 작성할게요
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { InspectionInfo } from '../types';
import { ChevronRight, Building, User, Calendar, Phone, Home, Clock, Layers } from 'lucide-react';

interface InfoFormProps {
  initialData: InspectionInfo;
  onSubmit: (data: InspectionInfo) => void;
}

const InfoForm: React.FC<InfoFormProps> = ({ initialData, onSubmit }) => {
  const [formData, setFormData] = useState<InspectionInfo>(initialData);

  // Load draft from localStorage if initialData is empty (fresh start)
  useEffect(() => {
    const isInitialEmpty = !initialData.apartmentName && !initialData.inspectorName;
    if (isInitialEmpty) {
      const draft = localStorage.getItem('info_form_draft');
      if (draft) {
        try {
          setFormData(JSON.parse(draft));
        } catch (e) {
          console.error("Failed to parse draft", e);
        }
      }
    }
  }, [initialData]);

  // Save draft to localStorage on change
  useEffect(() => {
    localStorage.setItem('info_form_draft', JSON.stringify(formData));
  }, [formData]);

  const formatPhoneNumber = (value: string) => {
    const cleaned = value.replace(/\D/g, '');
    if (cleaned.length < 4) return cleaned;
    if (cleaned.length < 7) return `${cleaned.slice(0, 3)}-${cleaned.slice(3)}`;
    if (cleaned.length < 11) return `${cleaned.slice(0, 3)}-${cleaned.slice(3, 7)}-${cleaned.slice(7)}`;
    return `${cleaned.slice(0, 3)}-${cleaned.slice(3, 7)}-${cleaned.slice(7, 11)}`;
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;

    if (name === 'phoneNumber') {
      const formatted = formatPhoneNumber(value);
      setFormData(prev => ({ ...prev, [name]: formatted }));
    } else {
      setFormData(prev => ({ ...prev, [name]: value }));
    }
  };

  // Helper to extract parts safely for Unit (Dong/Ho)
  const getUnitParts = (str: string) => {
    // Expected format: "101동 / 1004호"
    if (str && str.includes('동')) {
      const parts = str.split('동');
      const d = parts[0].trim();
      const h = parts[1] ? parts[1].replace('/', '').replace('호', '').trim() : '';
      return { d, h };
    }
    // Fallback if data format doesn't match
    return { d: str, h: '' };
  };

  // Extract pure value from "84 타입 / 평" format
  const getTypeVal = (str: string) => {
    if (!str) return '';
    // If user has old format data "84타입 / 34평", just show it as is or try to extract
    // But for the new requirement, we assume standard format ends with " 타입 / 평"
    return str.replace(' 타입 / 평', '');
  };

  const { d: dong, h: ho } = getUnitParts(formData.unit);
  const typeVal = getTypeVal(formData.typeSize);

  const handleUnitChange = (part: 'first' | 'second', value: string) => {
    const newDong = part === 'first' ? value : dong;
    const newHo = part === 'second' ? value : ho;
    // Combine back to standard string
    const combined = newDong || newHo ? `${newDong}동 / ${newHo}호` : '';
    setFormData(prev => ({ ...prev, unit: combined }));
  };

  const handleTypeChange = (value: string) => {
    // Store as "Value 타입 / 평"
    const combined = value ? `${value} 타입 / 평` : '';
    setFormData(prev => ({ ...prev, typeSize: combined }));
  };

  // Date/Time Handling Helpers
  const [datePart, timePart] = formData.date.split('T');
  const [hourPart, minutePart] = (timePart || '09:00').split(':');

  const handleDatePartChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newDate = e.target.value;
    setFormData(prev => {
        // preserve existing time or default to current rounded time
        const currentTime = prev.date.split('T')[1] || '09:00';
        return { ...prev, date: `${newDate}T${currentTime}` };
    });
  };

  const handleHourChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const newHour = e.target.value;
    setFormData(prev => {
        const currentDate = prev.date.split('T')[0];
        const currentMinute = (prev.date.split('T')[1] || '00:00').split(':')[1];
        return { ...prev, date: `${currentDate}T${newHour}:${currentMinute}` };
    });
  };

  const handleMinuteChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const newMinute = e.target.value;
    setFormData(prev => {
        const currentDate = prev.date.split('T')[0];
        const currentHour = (prev.date.split('T')[1] || '00:00').split(':')[0];
        return { ...prev, date: `${currentDate}T${currentHour}:${newMinute}` };
    });
  };

  const hours = Array.from({ length: 24 }, (_, i) => String(i).padStart(2, '0'));
  const minutes = ['00', '10', '20', '30', '40', '50'];

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Check for empty required fields
    if (
      !formData.apartmentName.trim() || 
      !formData.unit.trim() || 
      !formData.typeSize.trim() ||
      !formData.inspectorName.trim() || 
      !formData.phoneNumber.trim() || 
      !formData.date.trim()
    ) {
      alert('아직 작성하지 않은 빈칸이 있습니다. 모든 필수 정보를 입력해주세요.');
      return;
    }

    onSubmit(formData);
  };

  return (
    <div className="w-full max-w-md mx-auto bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
      <div className="text-center mb-8">
        <h2 className="text-2xl font-bold text-gray-800">현장 정보 입력</h2>
        <p className="text-gray-500 text-sm mt-2">점검 보고서 생성을 위한 기초 정보를 입력해주세요.</p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">아파트명 <span className="text-red-500">*</span></label>
          <div className="relative">
            <Building className="absolute left-3 top-3 h-5 w-5 text-gray-400" />
            <input
              type="text"
              name="apartmentName"
              value={formData.apartmentName}
