export const generatePDFBlob = async (info: InspectionInfo, defects: DefectItem[]): Promise<Blob> => {
  const pdf = new jsPDF('p', 'mm', 'a4');
  const pageWidth = pdf.internal.pageSize.getWidth();
  const pageHeight = pdf.internal.pageSize.getHeight();
  let cursorY = 0;

  const container = document.createElement('div');
  container.style.width = '794px'; 
  container.style.position = 'fixed';
  container.style.top = '0';
  container.style.left = '0';
  container.style.zIndex = '-9999';
  container.style.backgroundColor = 'white';
  document.body.appendChild(container);

  // --- Rendering Helpers ---

  // 1. Render and add to PDF immediately (legacy mode or for simple blocks)
  const captureAndAdd = async (html: string) => {
    container.innerHTML = html;
    await new Promise(resolve => setTimeout(resolve, 50));

    const canvas = await html2canvas(container, {
      scale: 1.5,
      useCORS: true,
      logging: false,
      windowWidth: 794,
      allowTaint: true,
      backgroundColor: '#ffffff'
    });

    const imgData = canvas.toDataURL('image/jpeg', 0.85); 
    const imgHeight = (canvas.height * pageWidth) / canvas.width;

    if (cursorY + imgHeight > pageHeight) {
      pdf.addPage();
      cursorY = 0;
    }

    pdf.addImage(imgData, 'JPEG', 0, cursorY, pageWidth, imgHeight);
    cursorY += imgHeight;
    container.innerHTML = '';
  };

  // 2. Render to Image Data ONLY (don't add to PDF yet). Used for size checking.
  const renderToImageData = async (html: string) => {
    container.innerHTML = html;
    await new Promise(resolve => setTimeout(resolve, 50));
    const canvas = await html2canvas(container, {
      scale: 1.5,
      useCORS: true,
      logging: false,
      windowWidth: 794,
      allowTaint: true,
      backgroundColor: '#ffffff'
    });
    const imgHeight = (canvas.height * pageWidth) / canvas.width;
    const imgData = canvas.toDataURL('image/jpeg', 0.85);
    container.innerHTML = '';
    return { imgData, imgHeight };
  };

  try {
    // 1. HEADER
    const headerHtml = `
      <div style="width: 794px; font-family: 'Apple SD Gothic Neo', 'Malgun Gothic', sans-serif; background: #fff;">
        <div style="background-color: #0284c7; padding: 45px 50px;">
